window.CS_DATA.push(...[{"id":"css:view-transition-name","lang":"css","name":"view-transition-name","zh":"视图过渡名称","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"为元素命名以参与视图过渡","desc":"给元素一个唯一标识，使页面切换（如 SPA 路由跳转）时浏览器为它单独生成快照，从而做出元素在旧页面与新页面之间移动的动画。默认 none 表示不单独捕获，跟随根快照一起过渡。同一时刻页面上同名元素只能有一个，重复会导致整个视图过渡被跳过；match-element 为较新取值，由浏览器自动匹配元素。","syntax":"none | <custom-ident> | match-element","attrs":[],"values":[{"v":"none","d":"不单独捕获该元素（初始值）。"},{"v":"<custom-ident>","d":"自定义唯一名称，不能使用 none、initial 等保留字。"},{"v":"match-element","d":"由浏览器自动为元素生成匹配的名称，减少手写命名。"}],"example":".demo {\n  view-transition-name: card;\n}","notes":["同一页面内名称必须唯一，重复会让整次视图过渡失效。","Chrome/Edge 111+、Safari 18+、Firefox 144+ 支持，旧版浏览器直接忽略。"],"keywords":["视图过渡","快照","动画","命名"],"aliases":["视图过渡名称","过渡名称","view-transition-name"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-transition-name","order":655,"js":"viewTransitionName","specGroups":["CSS View Transitions"],"meta":{"initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"111","firefox":"144","safari":"18","edge":"111"}},{"id":"css:view-transition-scope","lang":"css","name":"view-transition-scope","zh":"视图过渡作用域","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"控制视图过渡快照的捕获范围","desc":"限定视图过渡快照的捕获作用域：none 沿用默认捕获规则，all 让该元素子树中符合条件的内容都纳入当前过渡。属于 View Transitions 规范较新加入的部分，浏览器实现很新。一般与 view-transition-name 搭配，用于局部区域过渡或避免全局捕获。","syntax":"none | all","attrs":[],"values":[{"v":"none","d":"使用默认捕获规则（初始值）。"},{"v":"all","d":"让子树内符合条件的元素都参与本次视图过渡。"}],"example":".demo {\n  view-transition-scope: all;\n}","notes":["很新的属性，目前仅 Chrome/Edge 147 起支持，Firefox 与 Safari 未实现。","单独使用几乎看不到效果，通常与 view-transition-name 或其他过渡声明配合。"],"keywords":["视图过渡","作用域","实验性","快照"],"aliases":["视图过渡作用域","过渡范围","view-transition-scope"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-transition-scope","order":656,"js":"viewTransitionScope","specGroups":["CSS View Transitions"],"meta":{"initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"147","firefox":"✗","safari":"✗","edge":"147"}},{"id":"css:animation-range","lang":"css","name":"animation-range","zh":"动画范围","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"简写设置滚动动画的起止范围","desc":"在滚动驱动动画中限定动画在时间线上哪一段播放，简写依次接受 animation-range-start 与 animation-range-end，可逗号分隔多组。常见写法如 entry 0% cover 100%，表示元素从进入视口到覆盖视口结束时播完。只对 animation-timeline 指定的滚动或视图时间线有意义。","syntax":"[ <'animation-range-start'> <'animation-range-end'>? ]#","attrs":[],"values":[{"v":"normal normal","d":"起止都使用时间线默认范围（初始值，等价于不限定）。"},{"v":"entry 0% exit 100%","d":"从进入视口开始到离开视口结束。"},{"v":"cover 0% cover 100%","d":"覆盖元素穿过可视区的整个过程。"},{"v":"<length-percentage>","d":"直接给出起点与终点位置，如 0% 100%。"}],"example":".demo {\n  animation-timeline: view();\n  animation-range: entry 0% cover 50%;\n}","notes":["实验性能力，Chrome/Edge 115+、Firefox 159+、Safari 26+ 支持，旧版浏览器忽略该声明。","展开为 animation-range-start 与 animation-range-end 两个长写属性。"],"keywords":["滚动动画","时间线","范围","简写"],"aliases":["动画范围","滚动动画范围","animation-range"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["可动画","实验性","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-range","order":130,"js":"animationRange","specGroups":["Scroll-driven Animations"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"相对时间线范围（未指定时为整条时间线）","appliesTo":"所有元素","computed":"由各长写属性决定","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:animation-range-end","lang":"css","name":"animation-range-end","zh":"动画范围终点","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"设定滚动动画结束的时间线位置","desc":"定义滚动驱动动画在时间线上的结束点，可取 normal、长度或百分比，也可写“具名范围 + 位置”，如 cover 100%、exit 50%。它与 animation-range-start 共同决定播放区间，区间之外的滚动进度会被截断。属于 animation-range 简写展开的长写属性。","syntax":"[ normal | <length-percentage> | <timeline-range-name> <length-percentage>? ]#","attrs":[],"values":[{"v":"normal","d":"使用时间线的默认结束位置（初始值）。"},{"v":"<length-percentage>","d":"直接给出结束位置，如 80%。"},{"v":"<timeline-range-name> <length-percentage>?","d":"具名范围加可选位置，如 cover 100%、exit 50%。"}],"example":".demo {\n  animation-timeline: view();\n  animation-range-end: cover 100%;\n}","notes":["实验性属性，仅较新版本浏览器支持，旧版会整条声明失效。","百分比位置相对所选具名范围计算；未写具名范围时相对整条时间线。"],"keywords":["滚动动画","时间线","结束点","范围"],"aliases":["动画结束范围","范围终点","animation-range-end"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-range-end","order":131,"js":"animationRangeEnd","specGroups":["Scroll-driven Animations"],"meta":{"initial":"normal","inherited":"否","animation":"不可动画","percentages":"相对时间线范围（未指定时为整条时间线）","appliesTo":"所有元素","computed":"列表逐项计算","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:animation-range-start","lang":"css","name":"animation-range-start","zh":"动画范围起点","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"设定滚动动画开始的时间线位置","desc":"定义滚动驱动动画在时间线上的起点，取值 normal、长度百分比，或“具名范围 + 位置”，如 entry 0%。它与 animation-range-end 组成播放区间，起点晚于终点时动画会被压缩甚至跳过。属于 animation-range 简写展开的长写属性，需滚动时间线才生效。","syntax":"[ normal | <length-percentage> | <timeline-range-name> <length-percentage>? ]#","attrs":[],"values":[{"v":"normal","d":"使用时间线的默认起点（初始值）。"},{"v":"<length-percentage>","d":"直接给出起点位置，如 20%。"},{"v":"<timeline-range-name> <length-percentage>?","d":"具名范围加可选位置，如 entry 0%、cover 30%。"}],"example":".demo {\n  animation-timeline: view();\n  animation-range-start: entry 20%;\n}","notes":["实验性属性，旧版浏览器会忽略该声明。","起止值颠倒不会报错，但动画区间可能为空或异常缩短。"],"keywords":["滚动动画","时间线","起点","范围"],"aliases":["动画起始范围","范围起点","animation-range-start"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-range-start","order":132,"js":"animationRangeStart","specGroups":["Scroll-driven Animations"],"meta":{"initial":"normal","inherited":"否","animation":"不可动画","percentages":"相对时间线范围（未指定时为整条时间线）","appliesTo":"所有元素","computed":"列表逐项计算","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:animation-timeline","lang":"css","name":"animation-timeline","zh":"动画时间线","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"指定动画驱动所依据的时间线","desc":"把 CSS 动画的进度绑定到滚动或视图时间线上，而不是默认的文档时间线，从而做出滚动到某处才播放的效果。常用值有 scroll()（相对滚动容器）、view()（元素进出视口）、none（不绑定），也可引用由 scroll-timeline-name、view-timeline-name 定义的具名时间线。绑定后播放进度由滚动位置决定，animation-duration 不再控制速度。","syntax":"<single-animation-timeline>#","attrs":[],"values":[{"v":"auto","d":"使用默认文档时间线（初始值）。"},{"v":"none","d":"不绑定时间线，动画不随滚动推进。"},{"v":"scroll()","d":"绑定最近的滚动容器，可写轴与作用域，如 scroll(nearest block)。"},{"v":"view()","d":"绑定元素在滚动视口中的可见进度。"},{"v":"<dashed-ident>","d":"引用具名时间线，如 --page-timeline。"}],"example":".demo {\n  animation-name: slide-in;\n  animation-timeline: view();\n}","notes":["实验性能力，Chrome/Edge 115+、Firefox 159+、Safari 26+ 支持，旧版浏览器忽略。","绑定滚动时间线后，animation-duration 不再决定播放速度，进度由滚动位置映射。"],"keywords":["滚动动画","时间线","滚动驱动","实验性"],"aliases":["动画时间线","滚动时间线","animation-timeline"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-timeline","order":133,"js":"animationTimeline","specGroups":["CSS Animations"],"meta":{"initial":"auto","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"列表逐项计算（标识符 / none / auto）","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:timeline-scope","lang":"css","name":"timeline-scope","zh":"时间线作用域","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"扩大具名时间线的可引用范围","desc":"默认情况下具名时间线只能被其后代元素引用，timeline-scope 可以把指定名称的作用域提升到该元素所在的子树，让兄弟或祖先元素也能用 animation-timeline: --name 引用。取值为 none 或以 -- 开头的标识符列表。它是滚动驱动动画的配套属性，用于跨分支共享时间线。","syntax":"none | <dashed-ident>#","attrs":[],"values":[{"v":"none","d":"不扩大作用域（初始值）。"},{"v":"<dashed-ident>#","d":"一个或多个以 -- 开头的时间线名称，逗号分隔。"}],"example":".demo {\n  timeline-scope: --page-timeline;\n}","notes":["实验性属性，Chrome/Edge 116+、Firefox 159+、Safari 26+ 支持。","名称必须与 scroll-timeline-name 或 view-timeline-name 中定义的名称一致。"],"keywords":["滚动动画","时间线","作用域","具名"],"aliases":["时间线作用域","timeline-scope"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/timeline-scope","order":622,"js":"timelineScope","specGroups":["Scroll-driven Animations"],"meta":{"initial":"none","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"none 或有序标识符列表","tier":"extra"},"browser":{"chrome":"116","firefox":"159","safari":"26","edge":"116"}},{"id":"css:view-timeline","lang":"css","name":"view-timeline","zh":"视图时间线","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"简写定义元素进出视口的时间线","desc":"视图时间线的简写，按顺序接受名称（view-timeline-name）、轴（view-timeline-axis）与可选的 inset（view-timeline-inset），可逗号分隔多组。定义之后，后代元素可用 animation-timeline: --名称 让动画跟随该元素进入、穿过、离开滚动容器的过程推进。名称必须以 -- 开头。","syntax":"[ <'view-timeline-name'> [ <'view-timeline-axis'> || <'view-timeline-inset'> ]? ]#","attrs":[],"values":[{"v":"--name","d":"只写名称，轴默认 block。"},{"v":"--name block","d":"指定名称与滚动轴。"},{"v":"--name inline inset 10%","d":"指定名称、轴与内缩，进一步调整可见判定范围。"}],"example":".demo {\n  view-timeline: --reveal block;\n}","notes":["实验性：Chrome/Edge 115+、Firefox 159+、Safari 26+ 支持，旧版浏览器忽略。","展开为 view-timeline-name、view-timeline-axis、view-timeline-inset。"],"keywords":["滚动动画","时间线","视口","简写"],"aliases":["视图时间线","view-timeline"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["可动画","实验性","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-timeline","order":650,"js":"viewTimeline","specGroups":["Scroll-driven Animations"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"所有元素","computed":"由各长写属性决定","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:view-timeline-axis","lang":"css","name":"view-timeline-axis","zh":"视图时间线轴","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"指定视图时间线的滚动方向轴","desc":"决定元素进出视口时按哪个方向计算进度：block 为块轴（横排文字下即垂直方向，默认），inline 为行内轴（横排下为水平），x、y 为固定物理轴。可逗号分隔多组对应多条视图时间线。只有滚动方向与元素可见性变化方向一致时，动画才会随滚动推进。","syntax":"[ block | inline | x | y ]#","attrs":[],"values":[{"v":"block","d":"块轴，横排文字下为垂直方向（初始值）。"},{"v":"inline","d":"行内轴，横排文字下为水平方向。"},{"v":"x","d":"固定水平方向，不受书写模式影响。"},{"v":"y","d":"固定垂直方向。"}],"example":".demo {\n  view-timeline-name: --reveal;\n  view-timeline-axis: x;\n}","notes":["实验性属性，旧版浏览器不支持，会忽略整条声明。","与 view-timeline-name 配套使用，也可用 view-timeline 简写一次写完。"],"keywords":["滚动动画","时间线","轴向","实验性"],"aliases":["视图时间线轴","滚动轴","view-timeline-axis"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-timeline-axis","order":651,"js":"viewTimelineAxis","specGroups":["Scroll-driven Animations"],"meta":{"initial":"block","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:view-timeline-inset","lang":"css","name":"view-timeline-inset","zh":"视图时间线内缩","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"内缩视口以调整视图时间线范围","desc":"用长度或百分比向内收缩滚动容器的可见区域，改变元素“进入/离开视口”的判定边界；可写 1–2 个值分别对应起点边和终点边，auto 表示不额外内缩。常用来避开固定头部或以百分比让动画提前结束。百分比相对滚动视口在对应轴上的尺寸计算。","syntax":"[ [ auto | <length-percentage> ]{1,2} ]#","attrs":[],"values":[{"v":"auto","d":"不施加额外内缩（初始值）。"},{"v":"<length-percentage>","d":"单个值同时用于起点边与终点边。"},{"v":"<length-percentage>{1,2}","d":"两个值分别为起点边、终点边的内缩，如 10% 20%。"}],"example":".demo {\n  view-timeline-name: --reveal;\n  view-timeline-inset: 10% 0;\n}","notes":["实验性属性，仅较新版本浏览器实现，旧版忽略。","可写负值向外扩展判定范围，但需确认浏览器实现支持。"],"keywords":["滚动动画","时间线","内缩","视口"],"aliases":["视图时间线内缩","内缩距离","view-timeline-inset"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["可动画","实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-timeline-inset","order":652,"js":"viewTimelineInset","specGroups":["Scroll-driven Animations"],"meta":{"initial":"auto","inherited":"否","animation":"按计算值插值","percentages":"相对相关滚动端口对应维度","appliesTo":"所有元素","computed":"见规范","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:view-timeline-name","lang":"css","name":"view-timeline-name","zh":"视图时间线名称","cat":"animation","catName":"动画与过渡","catEn":"","catOrder":7,"summary":"为视图时间线命名以便引用","desc":"给元素定义一条具名视图时间线，名称必须以 -- 开头，之后后代元素可用 animation-timeline: --名称 让动画跟随该元素进出视口推进。可逗号分隔多个名称，默认 none 表示不定义。它是 view-timeline 简写展开的长写属性，常配合 timeline-scope 跨分支引用。","syntax":"[ none | <dashed-ident> ]#","attrs":[],"values":[{"v":"none","d":"不定义视图时间线（初始值）。"},{"v":"<dashed-ident>","d":"以 -- 开头的自定义名称，如 --reveal。"},{"v":"<dashed-ident>#","d":"多个名称，逗号分隔，可同时定义多条时间线。"}],"example":".demo {\n  view-timeline-name: --reveal;\n}","notes":["实验性属性，Chrome/Edge 115+、Firefox 159+、Safari 26+ 支持。","默认只有后代能引用该名称，跨分支引用需用 timeline-scope 提升作用域。"],"keywords":["滚动动画","时间线","命名","实验性"],"aliases":["视图时间线名称","时间线命名","view-timeline-name"],"status":"experimental","statusLabel":"实验性","hot":false,"tags":["实验性"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/view-timeline-name","order":653,"js":"viewTimelineName","specGroups":["Scroll-driven Animations"],"meta":{"initial":"none","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"none 或有序标识符列表","tier":"extra"},"browser":{"chrome":"115","firefox":"159","safari":"26","edge":"115"}},{"id":"css:backface-visibility","lang":"css","name":"backface-visibility","zh":"背面可见性","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"控制元素背面是否可见","desc":"当元素经 3D 变换（如 rotateY(180deg)）翻转到背面时，决定背面显示还是隐藏。默认 visible 显示镜像内容，hidden 则整块背面不可见，常用于卡片翻转效果中防止背面文字透出。需要配合 transform-style: preserve-3d 或 perspective 才能体现 3D 层次。","syntax":"visible | hidden","attrs":[],"values":[{"v":"visible","d":"背面可见，显示镜像内容（初始值）。"},{"v":"hidden","d":"背面隐藏，翻转超过 90 度后不可见。"}],"example":".demo {\n  transform: rotateY(180deg);\n  backface-visibility: hidden;\n}","notes":["必须存在 3D 变换才有意义，纯 2D 旋转不会触发背面判断。","只在可变换元素上生效，行内非替换元素上通常无效。"],"keywords":["3D","翻转","变换","卡片"],"aliases":["背面可见性","背面隐藏","backface-visibility"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/backface-visibility","order":139,"js":"backfaceVisibility","specGroups":["CSS Transforms"],"meta":{"initial":"visible","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"15.4","edge":"12"}},{"id":"css:offset","lang":"css","name":"offset","zh":"偏移路径","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"简写设置元素沿路径运动","desc":"motion path 模块的简写，把 offset-position、offset-path、offset-distance、offset-rotate 与斜杠后的 offset-anchor 组合成一条声明，用于让元素沿指定路径定位或运动。offset-distance 可用百分比表示路径上的位置，对其做动画即可得到曲线运动轨迹。","syntax":"[ <'offset-position'>? [ <'offset-path'> [ <'offset-distance'> || <'offset-rotate'> ]? ]? ]! [ / <'offset-anchor'> ]?","attrs":[],"values":[{"v":"<offset-path> <offset-distance>","d":"路径加距离，如 path(\"M 0 0 L 100 100\") 50%。"},{"v":"<offset-path> / <offset-anchor>","d":"斜杠后指定元素贴合路径的锚点。"},{"v":"none","d":"不设置路径，各长写属性取初始值。"}],"example":".demo {\n  offset: path(\"M 0 0 L 120 60\") 50% auto;\n  position: relative;\n}","notes":["展开为 offset-position、offset-path、offset-distance、offset-rotate、offset-anchor。","Chrome 55+、Firefox 72+、Safari 16+ 支持，旧版浏览器直接忽略。"],"keywords":["动画","路径","简写","运动"],"aliases":["运动路径","偏移简写","offset"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset","order":452,"js":"offset","specGroups":["Motion Path"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"可变换元素","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"55","firefox":"72","safari":"16","edge":"79"}},{"id":"css:offset-anchor","lang":"css","name":"offset-anchor","zh":"偏移锚点","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"指定元素对齐路径的参考点","desc":"决定元素上的哪个点贴合路径位置，取值同 background-position 的位置语法，默认 auto 表示元素中心（即 50% 50%）。当元素视觉重心不在中心时（如图标带文字标签），调整锚点能让元素更自然地沿路径运动。它是 offset 简写中斜杠之后的部分。","syntax":"auto | <position>","attrs":[],"values":[{"v":"auto","d":"使用元素中心作为锚点（初始值）。"},{"v":"<position>","d":"位置值，如 center、top left、30% 70%，百分比相对元素自身尺寸。"}],"example":".demo {\n  offset-path: path(\"M 0 0 L 160 0\");\n  offset-anchor: bottom center;\n}","notes":["百分比相对元素自身宽高解析，不是相对路径或包含块。","Chrome/Edge 116 起才支持该长写属性，较旧版本只能用 offset 简写。"],"keywords":["动画","路径","锚点","位置"],"aliases":["偏移锚点","路径锚点","offset-anchor"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-anchor","order":453,"js":"offsetAnchor","specGroups":["Motion Path"],"meta":{"initial":"auto","inherited":"否","animation":"位置插值","percentages":"相对宽度与高度","appliesTo":"可变换元素","computed":"长度取绝对值，否则为百分比","tier":"core"},"browser":{"chrome":"116","firefox":"72","safari":"16","edge":"116"}},{"id":"css:offset-distance","lang":"css","name":"offset-distance","zh":"偏移距离","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"指定元素在路径上的位置","desc":"表示元素沿 offset-path 走到的位置，可用长度或百分比，百分比相对整条路径长度（0% 为起点、100% 为终点），默认 0。对它做动画（如 from 0% to 100%）即可让元素沿路径移动，常与 offset-rotate: auto 配合让元素朝向随路径切线变化。","syntax":"<length-percentage>","attrs":[],"values":[{"v":"<length>","d":"绝对长度，如 120px。"},{"v":"<length-percentage>","d":"百分比相对路径总长度，如 50%。"},{"v":"0","d":"初始值，元素位于路径起点。"}],"example":".demo {\n  offset-path: path(\"M 0 0 C 120 0 120 120 240 120\");\n  offset-distance: 40%;\n}","notes":["百分比以整条路径长度为基准，折线的各段映射可能不均匀。","属于 offset 简写的一部分，单独设置时需确保 offset-path 已定义。"],"keywords":["动画","路径","距离","进度"],"aliases":["偏移距离","路径距离","offset-distance"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-distance","order":454,"js":"offsetDistance","specGroups":["Motion Path"],"meta":{"initial":"0","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对路径总长度","appliesTo":"可变换元素","computed":"长度取绝对值，否则为百分比","tier":"core"},"browser":{"chrome":"55","firefox":"72","safari":"16","edge":"79"}},{"id":"css:offset-path","lang":"css","name":"offset-path","zh":"偏移路径","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"定义元素运动的路径","desc":"指定元素沿哪条路径定位或运动，可取 none、基本形状（circle()、ellipse()、inset()）、path() 的 SVG 路径数据、ray() 射线，或用 url() 引用 SVG 路径元素，还可附加坐标盒。路径本身不改变元素尺寸，只决定 offset-distance 的位置基准与 offset-rotate 的方向。","syntax":"none | <offset-path> || <coord-box>","attrs":[],"values":[{"v":"none","d":"不定义路径（初始值）。"},{"v":"path(\"M 0 0 L 100 100\")","d":"SVG 路径字符串，可做曲线运动。"},{"v":"circle(50%)","d":"圆形路径，元素绕圆运动。"},{"v":"ray(45deg)","d":"从起点沿指定角度出发的射线。"},{"v":"url(#svgPath)","d":"引用页面中 SVG 的路径元素。"},{"v":"<coord-box>","d":"附加坐标盒，如 border-box、fill-box。"}],"example":".demo {\n  offset-path: circle(40%);\n  offset-distance: 25%;\n}","notes":["Chrome 55+、Firefox 72+、Safari 15.4+ 支持，旧版不支持 path() 与 ray()。","路径坐标默认相对元素自身边框盒，SVG 元素可用 fill-box 改为相对几何包围盒。"],"keywords":["动画","路径","形状","运动"],"aliases":["偏移路径","运动路径","offset-path"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-path","order":455,"js":"offsetPath","specGroups":["Motion Path"],"meta":{"initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"55","firefox":"72","safari":"15.4","edge":"79"}},{"id":"css:offset-position","lang":"css","name":"offset-position","zh":"偏移起始位置","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"设定偏移路径的起始参考位置","desc":"定义路径坐标系的原点位置，取值 normal、auto 或位置值（如 50% 50%、left top），默认 normal。使用 ray() 或相对包含块的路径时，起点由它决定。它与 offset-anchor 不同：这里定义路径原点，而锚点定义元素上贴合路径的点。","syntax":"normal | auto | <position>","attrs":[],"values":[{"v":"normal","d":"使用默认的 50% 50%（初始值）。"},{"v":"auto","d":"由元素布局位置决定路径起点。"},{"v":"<position>","d":"显式位置，如 left top、20% 80%。"}],"example":".demo {\n  offset-path: ray(60deg);\n  offset-position: 20% 50%;\n}","notes":["Chrome/Edge 116+、Firefox 122+、Safari 16+ 支持，旧版浏览器忽略。","单独的 offset-position 在没有 offset-path 时通常不产生可见效果。"],"keywords":["动画","路径","起点","位置"],"aliases":["偏移起始位置","路径起点","offset-position"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-position","order":456,"js":"offsetPosition","specGroups":["Motion Path"],"meta":{"initial":"normal","inherited":"否","animation":"位置插值","percentages":"相对包含块尺寸","appliesTo":"可变换元素","computed":"长度取绝对值，否则为百分比","tier":"core"},"browser":{"chrome":"116","firefox":"122","safari":"16","edge":"116"}},{"id":"css:offset-rotate","lang":"css","name":"offset-rotate","zh":"偏移旋转","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"控制元素沿路径时的朝向","desc":"决定元素在路径上是否随路径方向旋转：auto 让元素朝向前进方向（默认，指向路径切线），reverse 反向朝向，也可附加角度做额外偏转，如 auto 45deg；单独写角度则固定朝向，0deg 表示始终不随路径转向。常用让箭头、车辆图标沿曲线自然转向。","syntax":"[ auto | reverse ] || <angle>","attrs":[],"values":[{"v":"auto","d":"跟随路径切线方向旋转（初始值）。"},{"v":"reverse","d":"朝路径切线反方向。"},{"v":"<angle>","d":"固定旋转角度，如 0deg 表示不随路径转向。"},{"v":"auto <angle>","d":"跟随切线并额外偏转，如 auto 90deg。"}],"example":".demo {\n  offset-path: path(\"M 0 0 Q 80 0 80 80\");\n  offset-rotate: auto 90deg;\n}","notes":["auto 依据路径切线计算；offset-path 为 none 时按 0 度处理。","属于 offset 简写的一部分，可与 offset-distance 一起使用。"],"keywords":["动画","路径","旋转","朝向"],"aliases":["偏移旋转","路径朝向","offset-rotate"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-rotate","order":457,"js":"offsetRotate","specGroups":["Motion Path"],"meta":{"initial":"auto","inherited":"否","animation":"角度 / 基本形状 / 路径插值","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"56","firefox":"72","safari":"16","edge":"79"}},{"id":"css:perspective","lang":"css","name":"perspective","zh":"透视距离","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"为 3D 变换设置透视景深","desc":"给子元素的三维变换添加透视效果：值越小透视越夸张、观察点越近，值越大越平缓。必须写在 3D 子元素的父容器上才能作用于子元素，自身同时会创建包含块，可能影响 position: fixed 后代的定位基准。none 表示不设透视（初始值）。","syntax":"none | <length>","attrs":[],"values":[{"v":"none","d":"不设透视（初始值）。"},{"v":"<length>","d":"透视距离，如 800px；通常取元素尺寸的数量级，过小会明显变形。"}],"example":".demo {\n  perspective: 900px;\n  transform-style: preserve-3d;\n}","notes":["写在父元素上才作用于子元素的 3D 变换，写在自己身上看不到透视。","会创建包含块，可能改变 position: fixed 后代的定位参照。"],"keywords":["3D","透视","变换","景深"],"aliases":["透视","景深","perspective"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/perspective","order":498,"js":"perspective","specGroups":["CSS Transforms"],"meta":{"initial":"none","inherited":"否","animation":"长度插值","percentages":"不适用","appliesTo":"可变换元素","computed":"见规范","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"9","edge":"12"}},{"id":"css:perspective-origin","lang":"css","name":"perspective-origin","zh":"透视原点","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"设置 3D 透视的观察位置","desc":"决定透视的观察点（消失点）位置，默认 50% 50% 即元素中心，取值与 background-position 相同的位置语法，两个百分比分别相对元素宽高。改变它可以让 3D 场景从左上或右下观察，产生不同的纵深方向。仅在父级设置了 perspective 时才有意义。","syntax":"<position>","attrs":[],"values":[{"v":"50% 50%","d":"元素中心（初始值）。"},{"v":"left top","d":"从左上角观察。"},{"v":"0% 100%","d":"从左下角观察。"}],"example":".demo {\n  perspective: 800px;\n  perspective-origin: left top;\n}","notes":["只有在父元素设置了 perspective 时才可见效果。","位置值解析方式与 background-position 相同。"],"keywords":["3D","透视","原点","观察"],"aliases":["透视原点","观察点","perspective-origin"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/perspective-origin","order":499,"js":"perspectiveOrigin","specGroups":["CSS Transforms"],"meta":{"initial":"50% 50%","inherited":"否","animation":"长度 / 百分比 / 颜色列表插值","percentages":"相对边界盒尺寸","appliesTo":"可变换元素","computed":"长度取绝对值，否则为百分比","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"9","edge":"12"}},{"id":"css:rotate","lang":"css","name":"rotate","zh":"旋转","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"独立设置元素旋转的变换","desc":"独立变换属性之一，只负责旋转：取值角度（如 45deg、0.25turn）或“轴 + 角度”（如 x 30deg），可绕 X/Y/Z 轴做 3D 旋转。与 transform: rotate() 相比，它能与 translate、scale 各自独立设置，合并顺序固定为平移、旋转、缩放，单独做动画也更方便。","syntax":"none | <angle> | [ x | y | z | <number>{3} ] && <angle>","attrs":[],"values":[{"v":"none","d":"不旋转（初始值）。"},{"v":"<angle>","d":"绕 Z 轴（屏幕平面）旋转，如 45deg。"},{"v":"x <angle>","d":"绕水平轴旋转，如 x 45deg。"},{"v":"y <angle>","d":"绕垂直轴旋转。"},{"v":"z <angle>","d":"绕垂直于屏幕的轴旋转。"},{"v":"<number>{3} <angle>","d":"自定义三维向量加角度。"}],"example":".demo {\n  rotate: 12deg;\n  transform-origin: center;\n}","notes":["Chrome/Edge 104+、Firefox 72+、Safari 14.1+ 支持，旧版需用 transform: rotate()。","独立变换按 translate→rotate→scale 顺序应用，与 transform 内函数的书写顺序不同。"],"keywords":["变换","旋转","3D","独立变换"],"aliases":["旋转","旋转角度","rotate"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/rotate","order":518,"js":"rotate","specGroups":["CSS Transforms"],"meta":{"initial":"none","inherited":"否","animation":"变换函数插值","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"104","firefox":"72","safari":"14.1","edge":"104"}},{"id":"css:scale","lang":"css","name":"scale","zh":"缩放","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"独立设置元素缩放比例的变换","desc":"独立变换属性，按比例缩放元素，可写 1–3 个数值或百分比，分别对应 X、Y、Z 轴；只写一个值时 X、Y 等比缩放。百分比写法（如 150% 等价于 1.5）属于较新语法。与 transform: scale() 相比便于单独做动画，也能与 translate、rotate 独立叠加。","syntax":"none | [ <number> | <percentage> ]{1,3}","attrs":[],"values":[{"v":"none","d":"不缩放（初始值）。"},{"v":"<number>","d":"单值等比缩放，如 1.2；0 会让元素完全不可见。"},{"v":"<number>{2}","d":"分别设置 X、Y，如 1.5 0.8。"},{"v":"<percentage>","d":"百分比写法，如 150% 等价于 1.5。"}],"example":".demo {\n  scale: 1.15;\n  transition: scale 0.2s ease;\n}","notes":["百分比取值属于较新语法，旧版浏览器只接受数字，建议优先写数字。","Chrome/Edge 104+、Firefox 72+、Safari 14.1+ 支持独立变换属性。"],"keywords":["变换","缩放","独立变换","动画"],"aliases":["缩放","缩放比例","scale"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scale","order":526,"js":"scale","specGroups":["CSS Transforms"],"meta":{"initial":"none","inherited":"否","animation":"变换函数插值","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"104","firefox":"72","safari":"14.1","edge":"104"}},{"id":"css:transform","lang":"css","name":"transform","zh":"变换","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"对元素应用二维或三维变换","desc":"用一条声明组合平移、旋转、缩放、倾斜等变换函数（translate()、rotate()、scale()、skew()、matrix() 等），多个函数按书写顺序依次应用，顺序不同结果差异很大。它不改变文档流布局，但会创建层叠上下文和包含块，常与 transition 搭配做交互动画。","syntax":"none | <transform-list>","attrs":[],"values":[{"v":"none","d":"无变换（初始值）。"},{"v":"translate(10px, 20px)","d":"二维平移。"},{"v":"rotate(45deg)","d":"绕元素中心旋转。"},{"v":"scale(1.2)","d":"等比缩放。"},{"v":"skewX(10deg)","d":"沿水平方向倾斜。"},{"v":"matrix(1,0,0,1,0,0)","d":"2D 变换矩阵，共 6 个值。"},{"v":"translate3d(0, 0, 100px)","d":"三维平移。"}],"example":".demo {\n  transform: translateX(20px) rotate(10deg);\n}","notes":["变换函数从右往左依次作用于元素坐标，书写顺序直接影响最终位置。","会创建包含块，使 position: fixed 后代相对它定位。","与独立变换 translate/rotate/scale 同时存在时，先应用独立属性再应用 transform。"],"keywords":["变换","平移","旋转","缩放"],"aliases":["变换","变形","transform"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform","order":634,"js":"transform","specGroups":["CSS Transforms"],"meta":{"initial":"none","inherited":"否","animation":"变换函数插值","percentages":"相对边界盒尺寸","appliesTo":"可变换元素","computed":"按指定值，长度转为绝对值","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"9","edge":"12"}},{"id":"css:transform-box","lang":"css","name":"transform-box","zh":"变换参考盒","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"定义变换原点相对哪个盒子","desc":"指定 transform-origin 与变换所参考的盒子：border-box、content-box、fill-box（SVG 图形自身包围盒）、stroke-box、view-box（最近 SVG 视口，初始值）。在 SVG 中对单个图形做旋转或缩放时常需设为 fill-box，否则原点按整个视口计算，元素位置会明显偏移。","syntax":"content-box | border-box | fill-box | stroke-box | view-box","attrs":[],"values":[{"v":"view-box","d":"最近 SVG 视口作为参考盒（初始值）。"},{"v":"border-box","d":"元素的边框盒。"},{"v":"content-box","d":"元素的内容盒。"},{"v":"fill-box","d":"SVG 图形填充区域的包围盒，适合对单个图形做变换。"},{"v":"stroke-box","d":"包含描边在内的包围盒。"}],"example":".demo {\n  transform: rotate(45deg);\n  transform-box: fill-box;\n  transform-origin: center;\n}","notes":["只影响 transform-origin 和变换的参考，不改变布局尺寸。","Chrome 64+、Firefox 55+、Safari 11+ 支持，旧版对 fill-box 支持较晚。"],"keywords":["变换","原点","SVG","盒子"],"aliases":["变换参考盒","变换盒子","transform-box"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform-box","order":635,"js":"transformBox","specGroups":["CSS Transforms"],"meta":{"initial":"view-box","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"64","firefox":"55","safari":"11","edge":"79"}},{"id":"css:transform-origin","lang":"css","name":"transform-origin","zh":"变换原点","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"设置元素变换的参考中心点","desc":"决定旋转、缩放、倾斜围绕哪个点进行，默认元素中心 50% 50% 0。可写一到两个位置分量，再加可选的 Z 轴长度，如 left top、20% 80% 30px，百分比相对元素自身宽高。做卡片翻转时常改为 center 或 bottom left；Z 轴分量只在 3D 变换中生效。","syntax":"[ <length-percentage> | left | center | right | top | bottom ] | [ [ <length-percentage> | left | center | right ] && [ <length-percentage> | top | center | bottom ] ] <length>?","attrs":[],"values":[{"v":"50% 50% 0","d":"元素中心（初始值）。"},{"v":"left top","d":"左上角。"},{"v":"0 0","d":"左上角（长度写法）。"},{"v":"50% 50% -50px","d":"中心点沿 Z 轴偏移，用于 3D 场景。"}],"example":".demo {\n  transform: rotate(20deg);\n  transform-origin: bottom left;\n}","notes":["百分比相对元素自身宽高计算，不是相对父元素。","第三个值只在 3D 变换中有意义，2D 下会被忽略。"],"keywords":["变换","原点","旋转","中心"],"aliases":["变换原点","旋转中心","transform-origin"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform-origin","order":636,"js":"transformOrigin","specGroups":["CSS Transforms"],"meta":{"initial":"50% 50% 0","inherited":"否","animation":"长度 / 百分比 / 颜色列表插值","percentages":"相对边界盒尺寸","appliesTo":"可变换元素","computed":"长度取绝对值，否则为百分比","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"9","edge":"12"}},{"id":"css:transform-style","lang":"css","name":"transform-style","zh":"变换样式","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"决定子元素是否保留三维空间","desc":"决定元素的子元素是在三维空间中保留各自位置（preserve-3d），还是被压平到元素所在平面（flat，初始值）。做 3D 卡片翻转、立方体时必须给父级设置 preserve-3d，否则子元素的 3D 变换会被拍扁。该属性影响整个子树的空间关系，不只是直接子元素。","syntax":"flat | preserve-3d","attrs":[],"values":[{"v":"flat","d":"子元素被压平到元素平面（初始值）。"},{"v":"preserve-3d","d":"子元素保留三维空间位置。"}],"example":".demo {\n  transform-style: preserve-3d;\n  perspective: 800px;\n}","notes":["需配合 perspective 与 3D 变换才能看到空间效果。","preserve-3d 会创建层叠上下文，注意与其他变换、滤镜属性的层叠交互。"],"keywords":["3D","变换","子元素","空间"],"aliases":["变换样式","3D空间","transform-style"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform-style","order":637,"js":"transformStyle","specGroups":["CSS Transforms"],"meta":{"initial":"flat","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"可变换元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"36","firefox":"16","safari":"9","edge":"12"}},{"id":"css:translate","lang":"css","name":"translate","zh":"平移","cat":"transform","catName":"变换与运动","catEn":"","catOrder":8,"summary":"独立设置元素平移的变换","desc":"独立变换属性，按 X、Y、Z 顺序平移元素，值可为长度或百分比（百分比相对元素自身尺寸），如 translate: 50% 0 会把元素水平移动自身宽度的一半。效果类似 transform: translate()，但不与 transform 中的其他函数互相覆盖，便于单独过渡。","syntax":"none | <length-percentage> [ <length-percentage> <length>? ]?","attrs":[],"values":[{"v":"none","d":"不平移（初始值）。"},{"v":"<length-percentage>","d":"单值只平移 X 轴。"},{"v":"<length-percentage> <length-percentage>","d":"分别设置 X、Y 方向平移。"},{"v":"<length-percentage> <length-percentage> <length>","d":"再加上 Z 轴，如 0 0 60px。"}],"example":".demo {\n  translate: 0 -8px;\n  transition: translate 0.2s ease;\n}","notes":["百分比相对元素自身宽高，与 left/top 相对包含块不同。","Chrome/Edge 104+、Firefox 72+、Safari 14.1+ 支持，旧版用 transform: translate()。"],"keywords":["变换","平移","独立变换","动画"],"aliases":["平移","位移","translate"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/translate","order":644,"js":"translate","specGroups":["CSS Transforms"],"meta":{"initial":"none","inherited":"否","animation":"变换函数插值","percentages":"相对边界盒尺寸","appliesTo":"可变换元素","computed":"按指定值，长度转为绝对值","tier":"core"},"browser":{"chrome":"104","firefox":"72","safari":"14.1","edge":"104"}},{"id":"css:border-collapse","lang":"css","name":"border-collapse","zh":"表格边框合并","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"控制表格单元格边框是否合并","desc":"仅用于 table 与 inline-table：separate（初始值）让相邻单元格各有独立边框，可用 border-spacing 设置间距；collapse 让相邻边框合并成一条，此时 border-spacing 失效，边框颜色与样式的合并规则也较复杂。表格是继承属性，子元素会继承该值，常配合去掉默认空隙。","syntax":"separate | collapse","attrs":[],"values":[{"v":"separate","d":"边框分离，相邻单元格各自显示边框（初始值）。"},{"v":"collapse","d":"边框合并，相邻边框合成一条。"}],"example":".demo {\n  border-collapse: collapse;\n  width: 100%;\n}","notes":["只对 display: table / inline-table 生效，普通元素上无效。","设为 collapse 后 border-spacing 不再起作用。","是继承属性，写在表格上会传递给内部单元格。"],"keywords":["表格","边框","合并","布局"],"aliases":["边框合并","表格边框","border-collapse"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/border-collapse","order":174,"js":"borderCollapse","specGroups":["CSS Table"],"meta":{"initial":"separate","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"表格元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1.1","edge":"12"}},{"id":"css:border-spacing","lang":"css","name":"border-spacing","zh":"表格边框间距","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"设置分离边框模式下单元格间距","desc":"在 border-collapse: separate 时指定相邻单元格边框之间的距离：写两个长度时第一个为水平间距、第二个为垂直间距，写一个则两个方向相同，默认 0。对 collapse 模式无效。想保留间距必须让表格保持分离边框，而不是合并边框。","syntax":"<length>{1,2}","attrs":[],"values":[{"v":"<length>","d":"水平与垂直间距相同，如 8px。"},{"v":"<length> <length>","d":"分别为水平、垂直间距，如 8px 4px。"},{"v":"0","d":"无间距（初始值）。"}],"example":".demo {\n  border-collapse: separate;\n  border-spacing: 8px 4px;\n}","notes":["只在 border-collapse: separate 下生效，collapse 时该值被忽略。","是继承属性，会由表格元素传给后代。","取值必须是非负长度，负数声明无效。"],"keywords":["表格","间距","边框","布局"],"aliases":["边框间距","单元格间距","border-spacing"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/border-spacing","order":206,"js":"borderSpacing","specGroups":["CSS Table"],"meta":{"initial":"0","inherited":"是","animation":"按计算值插值","percentages":"不适用","appliesTo":"表格元素","computed":"两个绝对长度","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:caption-side","lang":"css","name":"caption-side","zh":"标题位置","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"设置表格标题显示在表格上方或下方","desc":"控制 caption 元素渲染在表格上方（top，初始值）还是下方（bottom），通常设置给 table 元素并由标题继承。它是普通流布局，不占据表格行；在垂直书写模式下上下方向会随书写方向变化。旧规范曾定义 left、right，但主流浏览器未实现，不要依赖。","syntax":"top | bottom","attrs":[],"values":[{"v":"top","d":"标题位于表格上方（初始值）。"},{"v":"bottom","d":"标题位于表格下方。"}],"example":".demo {\n  caption-side: bottom;\n}","notes":["需设置给 table 元素，caption 会继承该值。","规范中的 left/right 值主流浏览器未实现，避免使用。","属于继承属性，直接写在 caption 上同样有效。"],"keywords":["表格","标题","布局","caption"],"aliases":["标题位置","表格标题","caption-side"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/caption-side","order":232,"js":"captionSide","specGroups":["CSS Table"],"meta":{"initial":"top","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"表格标题元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:counter-increment","lang":"css","name":"counter-increment","zh":"计数器递增","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"指定元素出现时计数器加多少","desc":"每当元素被渲染时，把指定计数器的值增加给定整数（默认 1），与 counter-reset 初始化、content: counter() 显示配合实现自定义编号。可一次声明多个“名称 增量”对，增量允许为负数或 0。它对每次元素出现都生效，嵌套元素会各自递增，常用于给章节、步骤自动编号。","syntax":"[ <counter-name> <integer>? ]+ | none","attrs":[],"values":[{"v":"<counter-name> <integer>?","d":"计数器名加可选增量，如 chapter 1；省略增量默认为 1。"},{"v":"none","d":"不递增任何计数器（初始值）。"},{"v":"chapter 2 section 1","d":"一次声明多个计数器，按顺序分别递增。"}],"example":".demo {\n  counter-reset: item;\n  counter-increment: item 2;\n}","notes":["增量可以是负数或 0，可用来跳过某个编号。","计数器作用域沿元素树继承，子元素与祖先操作的是同一份计数器。"],"keywords":["计数器","编号","列表","生成内容"],"aliases":["计数器递增","计数器加一","counter-increment"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/counter-increment","order":284,"js":"counterIncrement","specGroups":["CSS Lists and Counters"],"meta":{"initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"2","firefox":"1","safari":"3","edge":"12"}},{"id":"css:counter-reset","lang":"css","name":"counter-reset","zh":"计数器重置","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"创建或重置计数器的起始值","desc":"在元素上创建（若尚不存在）或重置指定计数器，默认重置为 0，也可写成“名称 起始值”。它是计数器体系的基础，配合 counter-increment 递增、content: counter(name) 输出编号。可一次重置多个计数器；reversed(name) 可声明倒数计数器，但浏览器支持不如普通写法广泛。","syntax":"[ <counter-name> <integer>? | <reversed-counter-name> <integer>? ]+ | none","attrs":[],"values":[{"v":"none","d":"不重置任何计数器（初始值）。"},{"v":"<counter-name>","d":"重置为 0，如 section。"},{"v":"<counter-name> <integer>","d":"重置为指定值，如 section 5。"},{"v":"reversed(<counter-name>)","d":"声明倒数计数器，输出时从后往前编号。"}],"example":".demo {\n  counter-reset: section 0;\n  counter-increment: section;\n}","notes":["重置发生在元素开始渲染时，与 counter-increment 的声明顺序会影响最终结果。","reversed() 写法较新，旧版浏览器可能整条声明失效。"],"keywords":["计数器","编号","重置","列表"],"aliases":["计数器重置","初始化计数器","counter-reset"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/counter-reset","order":285,"js":"counterReset","specGroups":["CSS Lists and Counters"],"meta":{"initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"2","firefox":"1","safari":"3","edge":"12"}},{"id":"css:counter-set","lang":"css","name":"counter-set","zh":"计数器赋值","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"直接设置计数器的当前值","desc":"与 counter-reset 不同，它只在同名计数器已存在时修改当前值，不会创建新计数器；作用域中不存在该计数器则声明不生效。取值为“名称 整数”对，默认设为 0。适合中途修正编号（例如跳过某章），浏览器实现较晚，旧版浏览器会忽略。","syntax":"[ <counter-name> <integer>? ]+ | none","attrs":[],"values":[{"v":"none","d":"不做任何设置（初始值）。"},{"v":"<counter-name> <integer>","d":"把已存在的计数器设为指定值，如 chapter 4。"},{"v":"<counter-name> <integer> <counter-name> <integer>","d":"一次设置多个计数器的值。"}],"example":".demo {\n  counter-reset: section;\n  counter-set: section 4;\n}","notes":["关键区别：counter-reset 会创建计数器，counter-set 只修改已存在的计数器。","Chrome 85+、Firefox 68+、Safari 17.2+ 支持，旧版浏览器忽略该声明。"],"keywords":["计数器","编号","赋值","列表"],"aliases":["计数器赋值","设置计数器","counter-set"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/counter-set","order":286,"js":"counterSet","specGroups":["CSS Lists and Counters"],"meta":{"initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"85","firefox":"68","safari":"17.2","edge":"85"}},{"id":"css:empty-cells","lang":"css","name":"empty-cells","zh":"空单元格","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"控制表格空单元格是否显示边框","desc":"在 border-collapse: separate 下，决定没有任何内容的单元格是否绘制边框和背景：show（初始值）照常显示，hide 则隐藏空单元格的边框，看起来像留白。只影响真正没有内容的单元格；包含文本或图片的格子不算空。常用于让稀疏的数据表格更干净。","syntax":"show | hide","attrs":[],"values":[{"v":"show","d":"绘制空单元格的边框（初始值）。"},{"v":"hide","d":"不绘制空单元格的边框与背景。"}],"example":".demo {\n  border-collapse: separate;\n  empty-cells: hide;\n}","notes":["仅在 border-collapse: separate 时生效，collapse 模式下被忽略。","包含 &nbsp; 或图片的单元格不算空，隐藏规则不会作用于它。"],"keywords":["表格","单元格","边框","布局"],"aliases":["空单元格","隐藏空单元格","empty-cells"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/empty-cells","order":295,"js":"emptyCells","specGroups":["CSS Table"],"meta":{"initial":"show","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"表格单元格元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1.2","edge":"12"}},{"id":"css:list-style","lang":"css","name":"list-style","zh":"列表样式","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"简写设置列表项的标记样式","desc":"列表标记三件套的简写，可任意组合 list-style-type、list-style-position、list-style-image，三者顺序不限。常写 list-style: none 去掉默认圆点，但列表的默认缩进仍在，通常还要设 padding: 0。只对 display: list-item 的元素生效，即 li 与 summary 等。","syntax":"<'list-style-type'> || <'list-style-position'> || <'list-style-image'>","attrs":[],"values":[{"v":"none","d":"去掉标记类型与图片，position 仍为初始值 outside。"},{"v":"disc inside","d":"实心圆点标记，且放在行内。"},{"v":"square url(bullet.svg)","d":"使用图片标记，图片加载失败时回退为 square。"},{"v":"decimal outside","d":"阿拉伯数字编号，标记在内容外侧。"}],"example":".demo {\n  list-style: square inside;\n  padding-left: 0;\n}","notes":["展开为 list-style-type、list-style-position、list-style-image。","简写会把省略的子属性重置为初始值，list-style: none 也会把 position 重置为 outside。"],"keywords":["列表","标记","简写","ul"],"aliases":["列表样式","列表标记","list-style"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/list-style","order":398,"js":"listStyle","specGroups":["CSS Lists and Counters"],"meta":{"initial":"由各长写属性决定","inherited":"是","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"列表项","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:list-style-image","lang":"css","name":"list-style-image","zh":"列表标记图片","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"用图片作为列表项的标记","desc":"指定自定义图片替代默认标记，取值为 url() 或渐变等图像值；默认 none 表示使用 list-style-type 的标记。图片会被缩放以适应标记框，位置受 list-style-position 控制。图片无法加载时会回退到 list-style-type，因此常同时保留一个 type 作为兜底。","syntax":"<image> | none","attrs":[],"values":[{"v":"none","d":"不使用图片标记（初始值），改用 list-style-type。"},{"v":"<image>","d":"图像值，如 url(bullet.svg)、linear-gradient(...)。"}],"example":".demo {\n  list-style-image: url(bullet.svg);\n  list-style-type: disc;\n}","notes":["图片尺寸由浏览器按标记框缩放，不能直接用 width/height 控制。","图片加载失败会回退到 list-style-type 的标记，建议保留兜底值。"],"keywords":["列表","图片","标记","url"],"aliases":["列表图片","自定义标记","list-style-image"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/list-style-image","order":399,"js":"listStyleImage","specGroups":["CSS Lists and Counters"],"meta":{"initial":"none","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"列表项","computed":"关键字 none、list-style-image 或计算值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:list-style-position","lang":"css","name":"list-style-position","zh":"列表标记位置","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"控制列表标记在内容内侧还是外侧","desc":"outside（初始值）把标记放在内容块外侧，多行文本换行时与文本左缘对齐；inside 把标记当作第一行行内内容，换行后的文本会缩进到标记下方。后者适合带背景或边框的列表项，但多行时排版不够整齐。它是 list-style 简写的一部分。","syntax":"inside | outside","attrs":[],"values":[{"v":"outside","d":"标记位于内容块外侧（初始值）。"},{"v":"inside","d":"标记作为第一行的行内内容。"}],"example":".demo {\n  list-style-position: inside;\n  list-style-type: decimal;\n}","notes":["inside 时多行文本第二行会顶到标记下方，视觉对齐不如 outside 规整。","只对 display: list-item 的元素生效，主要作用于 li 与 summary。"],"keywords":["列表","标记","位置","缩进"],"aliases":["标记位置","列表缩进","list-style-position"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/list-style-position","order":400,"js":"listStylePosition","specGroups":["CSS Lists and Counters"],"meta":{"initial":"outside","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"列表项","computed":"按指定值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:list-style-type","lang":"css","name":"list-style-type","zh":"列表标记类型","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"设置列表项标记的样式","desc":"决定列表标记的外观，常用 disc、circle、square、decimal、lower-alpha、upper-roman、lower-greek 等关键字，也可写自定义字符串或引用 @counter-style 定义。none 只隐藏标记、保留列表项布局。改变有序列表的起始编号应使用 HTML start 属性或 counter-reset。","syntax":"<counter-style> | <string> | none","attrs":[],"values":[{"v":"disc","d":"实心圆点（初始值）。"},{"v":"circle","d":"空心圆圈。"},{"v":"square","d":"实心方块。"},{"v":"decimal","d":"阿拉伯数字 1. 2. 3."},{"v":"lower-alpha","d":"小写字母 a. b. c."},{"v":"upper-roman","d":"大写罗马数字 I. II. III."},{"v":"\"<string>\"","d":"自定义字符串标记，如 \"→ \"。"},{"v":"none","d":"不显示标记，但列表项缩进仍在。"}],"example":".demo {\n  list-style-type: upper-roman;\n}","notes":["none 不会去掉列表默认缩进，需要时再设 padding-left: 0。","自定义字符串标记在部分旧版浏览器上渲染可能不一致。"],"keywords":["列表","标记","编号","符号"],"aliases":["标记类型","项目符号","list-style-type"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/list-style-type","order":401,"js":"listStyleType","specGroups":["CSS Lists and Counters"],"meta":{"initial":"disc","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"列表项","computed":"按指定值","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:table-layout","lang":"css","name":"table-layout","zh":"表格布局算法","cat":"list","catName":"列表与表格","catEn":"","catOrder":9,"summary":"选择表格列宽的布局算法","desc":"fixed 采用固定布局：列宽由首行单元格或 col 的宽度决定，与后续内容无关，渲染更快且结果可预测，但内容过长会溢出或换行；auto（初始值）根据全部内容自动分配列宽，适合内容不定但计算更慢。固定布局需要给表格设置明确宽度才明显生效。","syntax":"auto | fixed","attrs":[],"values":[{"v":"auto","d":"根据内容自动计算列宽（初始值）。"},{"v":"fixed","d":"按首行单元格与 col 定义确定列宽，与后续内容无关。"}],"example":".demo {\n  table-layout: fixed;\n  width: 100%;\n}","notes":["fixed 时过长的内容可能溢出单元格，需配合 word-break 或 overflow 处理。","表格没有明确宽度时，fixed 的效果不明显。"],"keywords":["表格","布局","列宽","性能"],"aliases":["表格布局","固定表格布局","table-layout"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/table-layout","order":586,"js":"tableLayout","specGroups":["CSS Table"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"表格元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"14","firefox":"1","safari":"1","edge":"12"}},{"id":"css:line-clamp","lang":"css","name":"line-clamp","zh":"行数限制","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"限制块级文本显示的最大行数","desc":"把块容器限制为最多若干行，超出的部分被裁剪，常配合省略号做多行截断；none 表示不限制。标准写法仍在推进，实际项目中普遍使用 -webkit-line-clamp 配合 display: -webkit-box、-webkit-box-orient: vertical 与 overflow: hidden 实现多行省略。","syntax":"none | <integer>","attrs":[],"values":[{"v":"none","d":"不限制行数（初始值）。"},{"v":"<integer>","d":"最大显示行数，如 2 或 3。"}],"example":".demo {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 2;\n  overflow: hidden;\n}","notes":["标准 line-clamp 支持尚不普及，生产环境通常写 -webkit-line-clamp，并同时设置 display: -webkit-box、-webkit-box-orient: vertical 与 overflow: hidden。","只适用于块容器，多列容器中不生效。"],"keywords":["文本","截断","省略号","溢出"],"aliases":["行数限制","多行省略","line-clamp"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/line-clamp","order":394,"js":"lineClamp","specGroups":["CSS Overflow"],"meta":{"initial":"none","inherited":"否","animation":"整数插值","percentages":"不适用","appliesTo":"除多列容器外的块级容器","computed":"按指定值","tier":"core"},"browser":{"chrome":"-webkit-6","firefox":"-webkit-68","safari":"preview","edge":"-webkit-79"}},{"id":"css:overflow","lang":"css","name":"overflow","zh":"溢出处理","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"简写设置内容溢出时的处理方式","desc":"同时控制水平与垂直方向的溢出行为：visible 溢出可见、hidden 裁剪、scroll 始终显示滚动条、auto 按需出现滚动条、clip 裁剪且不可滚动。写一个值两轴相同，写两个值分别对应 x 与 y。注意只要一个轴不是 visible，另一个轴的 visible 会被计算为 auto。","syntax":"[ visible | hidden | clip | scroll | auto ]{1,2}","attrs":[],"values":[{"v":"visible","d":"内容溢出可见（初始值）。"},{"v":"hidden","d":"裁剪溢出内容，可由脚本滚动但不显示滚动条。"},{"v":"clip","d":"裁剪内容且完全不可滚动。"},{"v":"scroll","d":"始终显示滚动条。"},{"v":"auto","d":"只在需要时显示滚动条。"}],"example":".demo {\n  max-height: 240px;\n  overflow: auto;\n}","notes":["只设一个轴时，另一轴的 visible 会变成 auto，容易意外出现滚动条。","展开为 overflow-x 与 overflow-y。","clip 与 hidden 不同：clip 禁止任何滚动，hidden 仍可被脚本滚动。"],"keywords":["滚动","溢出","裁剪","滚动条"],"aliases":["溢出","溢出处理","overflow"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow","order":466,"js":"overflow","specGroups":["CSS Overflow"],"meta":{"initial":"visible","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"}},{"id":"css:overflow-anchor","lang":"css","name":"overflow-anchor","zh":"滚动锚定","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制元素是否参与滚动锚定","desc":"浏览器默认启用滚动锚定：上方插入内容时自动调整滚动位置，避免正在看的内容被顶走。auto（初始值）允许该元素参与锚定，none 让当前元素及其子树不参与，常用于轮播、聊天窗口等自行管理滚动的区域，防止浏览器自动修正与预期冲突。","syntax":"auto | none","attrs":[],"values":[{"v":"auto","d":"参与滚动锚定（初始值）。"},{"v":"none","d":"不参与滚动锚定，浏览器不据此调整滚动位置。"}],"example":".demo {\n  overflow-anchor: none;\n  overflow-y: auto;\n}","notes":["只在支持滚动锚定的浏览器上生效，旧版浏览器会忽略该声明。","写在滚动容器或其内部元素上都可，设为 none 的区域不参与锚定选择。"],"keywords":["滚动","锚定","跳动","滚动容器"],"aliases":["滚动锚定","锚定滚动","overflow-anchor"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-anchor","order":467,"js":"overflowAnchor","specGroups":["CSS Scroll Anchoring"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"56","firefox":"66","safari":"27","edge":"79"}},{"id":"css:overflow-block","lang":"css","name":"overflow-block","zh":"块轴溢出","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置块轴方向的溢出处理","desc":"逻辑属性，按书写模式映射到 overflow-y 或 overflow-x：横排文字下对应垂直方向，竖排时对应水平方向。取值与 overflow 相同，初始值为 auto；若另一轴为不相容的值时会按规则改写计算值。用它可以写出与书写方向无关的溢出规则。","syntax":"visible | hidden | clip | scroll | auto","attrs":[],"values":[{"v":"visible","d":"溢出可见。"},{"v":"hidden","d":"裁剪溢出内容。"},{"v":"clip","d":"裁剪且不可滚动。"},{"v":"scroll","d":"始终显示滚动条。"},{"v":"auto","d":"按需显示滚动条（初始值）。"}],"example":".demo {\n  overflow-block: auto;\n  overflow-inline: hidden;\n}","notes":["Chrome/Edge 135+、Firefox 69+、Safari 26+ 支持，旧版浏览器忽略。","横排文字下等价于 overflow-y，竖排时映射到 overflow-x。"],"keywords":["溢出","逻辑属性","块轴","书写模式"],"aliases":["块轴溢出","逻辑溢出","overflow-block"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-block","order":468,"js":"overflowBlock","specGroups":["CSS Overflow"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"按指定值（visible / clip 视另一值替换）","tier":"core"},"browser":{"chrome":"135","firefox":"69","safari":"26","edge":"135"}},{"id":"css:overflow-clip-margin","lang":"css","name":"overflow-clip-margin","zh":"溢出裁剪边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"扩展 overflow: clip 的裁剪边界","desc":"配合 overflow: clip 使用，决定裁剪边缘向外扩展多少再裁剪：取值由视觉盒（border-box、padding-box、content-box 等）与长度组成，如 border-box 12px 表示边框盒再多 12px 以内仍可见。默认 0px 即严格在边框盒处裁剪，可实现“稍微越界仍显示”的效果。","syntax":"<visual-box> || <length [0,∞]>","attrs":[],"values":[{"v":"<visual-box> || <length>","d":"视觉盒与扩展长度，如 border-box 12px，顺序不限。"},{"v":"0px","d":"不扩展，以边框盒裁剪（初始值）。"}],"example":".demo {\n  overflow: clip;\n  overflow-clip-margin: border-box 12px;\n}","notes":["只在 overflow: clip 时起作用，overflow: hidden 下无效。","Safari 尚未支持该属性，需要提供降级样式。"],"keywords":["裁剪","溢出","边距","clip"],"aliases":["裁剪边距","溢出裁剪边距","overflow-clip-margin"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-clip-margin","order":470,"js":"overflowClipMargin","specGroups":["CSS Overflow"],"meta":{"initial":"0px","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"见规范","tier":"core"},"browser":{"chrome":"90","firefox":"102","safari":"✗","edge":"90"}},{"id":"css:overflow-inline","lang":"css","name":"overflow-inline","zh":"行内轴溢出","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置行内轴方向的溢出处理","desc":"逻辑属性，按书写模式映射到水平或垂直方向的溢出：横排文字下对应 overflow-x，竖排时对应 overflow-y。取值与 overflow 相同，初始值 auto。与 overflow-block 成对使用，可只在一个轴上裁剪、另一个轴滚动，且规则不依赖书写方向。","syntax":"visible | hidden | clip | scroll | auto","attrs":[],"values":[{"v":"visible","d":"溢出可见。"},{"v":"hidden","d":"裁剪溢出内容。"},{"v":"clip","d":"裁剪且不可滚动。"},{"v":"scroll","d":"始终显示滚动条。"},{"v":"auto","d":"按需显示滚动条（初始值）。"}],"example":".demo {\n  overflow-inline: auto;\n  overflow-block: hidden;\n}","notes":["Chrome/Edge 135+、Firefox 69+、Safari 26+ 支持，旧版浏览器忽略。","横排文字下等价于 overflow-x，竖排时映射到 overflow-y。"],"keywords":["溢出","逻辑属性","行内轴","书写模式"],"aliases":["行内轴溢出","逻辑溢出","overflow-inline"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-inline","order":471,"js":"overflowInline","specGroups":["CSS Overflow"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"按指定值（visible / clip 视另一值替换）","tier":"core"},"browser":{"chrome":"135","firefox":"69","safari":"26","edge":"135"}},{"id":"css:overflow-wrap","lang":"css","name":"overflow-wrap","zh":"溢出换行","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制长单词在容器内如何折行","desc":"决定不可断开的字符串（长单词、URL、连续数字）超出容器时是否允许在任意字符处断行：normal 只在正常断点换行，可能溢出；break-word 必要时强制断行；anywhere 还会把断点计入最小内容宽度，影响 flex/grid 的尺寸计算。它是继承属性，与 word-break 作用不同。","syntax":"normal | break-word | anywhere","attrs":[],"values":[{"v":"normal","d":"只在正常断点换行，长单词可能溢出（初始值）。"},{"v":"break-word","d":"必要时在任意位置断行，但不影响最小内容宽度。"},{"v":"anywhere","d":"允许任意断行，且断点参与最小内容宽度计算。"}],"example":".demo {\n  overflow-wrap: anywhere;\n  max-width: 240px;\n}","notes":["是继承属性，会传给内部文本元素。","anywhere 与 break-word 的差异在 flex/grid 的最小尺寸计算上最明显。"],"keywords":["换行","文本","溢出","断行"],"aliases":["长词换行","溢出换行","overflow-wrap"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可继承","可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-wrap","order":472,"js":"overflowWrap","specGroups":["CSS Text"],"meta":{"initial":"normal","inherited":"是","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"文本元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"23","firefox":"49","safari":"7","edge":"18"}},{"id":"css:overflow-x","lang":"css","name":"overflow-x","zh":"水平溢出","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制水平方向的溢出行为","desc":"单独设置水平轴溢出：visible 溢出可见、hidden 裁剪、scroll 始终显示横向滚动条、auto 按需出现、clip 裁剪且不可滚动，默认 visible。常用于横向滚动列表、宽表格容器；只设一个轴时另一轴的 visible 会被改写为 auto，容易带来意外滚动条。","syntax":"visible | hidden | clip | scroll | auto","attrs":[],"values":[{"v":"visible","d":"水平溢出可见（初始值）。"},{"v":"hidden","d":"裁剪水平溢出内容。"},{"v":"scroll","d":"始终显示横向滚动条。"},{"v":"auto","d":"需要时显示横向滚动条。"},{"v":"clip","d":"裁剪且不可滚动。"}],"example":".demo {\n  overflow-x: auto;\n  white-space: nowrap;\n}","notes":["单独设置 overflow-x 会让 overflow-y 的 visible 计算为 auto，注意垂直方向是否意外出现滚动条。","scroll 在现代浏览器中可能使用覆盖式滚动条，不占据布局空间。"],"keywords":["滚动","溢出","水平","滚动条"],"aliases":["水平溢出","横向滚动","overflow-x"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-x","order":473,"js":"overflowX","specGroups":["CSS Overflow"],"meta":{"initial":"visible","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"按指定值（visible / clip 视另一值替换）","tier":"core"},"browser":{"chrome":"1","firefox":"3.5","safari":"3","edge":"12"}},{"id":"css:overflow-y","lang":"css","name":"overflow-y","zh":"垂直溢出","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制垂直方向的溢出行为","desc":"单独设置垂直轴溢出，常用 hidden、scroll、auto，默认 visible。用于固定高度容器内的滚动区域、折叠面板与聊天窗口等场景。它与 overflow-x 相互影响：只设一个轴时另一轴的 visible 会被计算为 auto，想让两个方向都不出现滚动条就必须同时显式设置。","syntax":"visible | hidden | clip | scroll | auto","attrs":[],"values":[{"v":"visible","d":"垂直溢出可见（初始值）。"},{"v":"hidden","d":"裁剪垂直溢出内容。"},{"v":"scroll","d":"始终显示纵向滚动条。"},{"v":"auto","d":"需要时显示纵向滚动条。"},{"v":"clip","d":"裁剪且不可滚动。"}],"example":".demo {\n  max-height: 200px;\n  overflow-y: auto;\n}","notes":["与 overflow-x 同时使用时保持取值一致，可避免意外的滚动条组合。","hidden 仍可通过脚本或焦点滚动内容，clip 则完全禁止滚动。"],"keywords":["滚动","溢出","垂直","滚动条"],"aliases":["垂直溢出","纵向滚动","overflow-y"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-y","order":474,"js":"overflowY","specGroups":["CSS Overflow"],"meta":{"initial":"visible","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"按指定值（visible / clip 视另一值替换）","tier":"core"},"browser":{"chrome":"1","firefox":"3.5","safari":"3","edge":"12"}},{"id":"css:overscroll-behavior","lang":"css","name":"overscroll-behavior","zh":"过度滚动行为","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"简写控制滚动到边界后的连锁行为","desc":"容器滚动到边界后继续滚动时，默认会带动页面整体滚动或触发下拉刷新，这叫连锁滚动。contain 阻止连锁但仍保留本地回弹反馈，none 同时禁用连锁与回弹，auto 为默认行为。写一个值两轴相同，写两个值先 x 后 y，常用于弹窗、抽屉与横向列表。","syntax":"[ contain | none | auto ]{1,2}","attrs":[],"values":[{"v":"auto","d":"默认行为，允许连锁滚动（初始值）。"},{"v":"contain","d":"阻止连锁到父级滚动容器，保留本地回弹反馈。"},{"v":"none","d":"阻止连锁并禁用本地回弹效果。"}],"example":".demo {\n  overscroll-behavior: contain;\n  overflow-y: auto;\n}","notes":["展开为 overscroll-behavior-x 与 overscroll-behavior-y。","iOS 的下拉刷新与弹性滚动对 none/contain 的响应与桌面浏览器不完全一致。"],"keywords":["滚动","边界","连锁滚动","回弹"],"aliases":["过度滚动","滚动边界行为","overscroll-behavior"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overscroll-behavior","order":476,"js":"overscrollBehavior","specGroups":["CSS Overscroll Behavior"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"非替换的块级与行内块元素","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"144","firefox":"150","safari":"16","edge":"18"}},{"id":"css:overscroll-behavior-block","lang":"css","name":"overscroll-behavior-block","zh":"块轴过度滚动","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制块轴方向的连锁滚动行为","desc":"逻辑属性，横排文字下映射到 overscroll-behavior-y，竖排时映射到 overscroll-behavior-x。取值 contain、none、auto，初始 auto。用于只在纵向阻止滚动穿透、横向保持默认行为，同时不把方向写死在属性名里。","syntax":"contain | none | auto","attrs":[],"values":[{"v":"auto","d":"默认行为（初始值）。"},{"v":"contain","d":"阻止向父级滚动容器连锁。"},{"v":"none","d":"阻止连锁并禁用回弹。"}],"example":".demo {\n  overscroll-behavior-block: contain;\n  overflow-y: auto;\n}","notes":["横排文字下等价于 overscroll-behavior-y，竖排时映射到 overscroll-behavior-x。","旧版浏览器不支持逻辑属性，可用 overscroll-behavior-x/y 作降级。"],"keywords":["滚动","边界","逻辑属性","块轴"],"aliases":["块轴过度滚动","逻辑过度滚动","overscroll-behavior-block"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overscroll-behavior-block","order":477,"js":"overscrollBehaviorBlock","specGroups":["CSS Overscroll Behavior"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"非替换的块级与行内块元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"144","firefox":"150","safari":"16","edge":"144"}},{"id":"css:overscroll-behavior-inline","lang":"css","name":"overscroll-behavior-inline","zh":"行内轴过度滚动","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制行内轴方向的连锁滚动行为","desc":"逻辑属性，横排文字下映射到 overscroll-behavior-x，竖排时映射到 overscroll-behavior-y。取值 contain、none、auto，初始 auto。横向轮播、筛选条常需要它阻止页面级横向滚动被带动，同时不影响纵向滚动。","syntax":"contain | none | auto","attrs":[],"values":[{"v":"auto","d":"默认行为（初始值）。"},{"v":"contain","d":"阻止连锁滚动，保留本地反馈。"},{"v":"none","d":"阻止连锁并禁用回弹。"}],"example":".demo {\n  overflow-x: auto;\n  overscroll-behavior-inline: contain;\n}","notes":["横排文字下等价于 overscroll-behavior-x，竖排时映射到 overscroll-behavior-y。","旧版浏览器不支持该逻辑属性，可用 overscroll-behavior-x/y 兜底。"],"keywords":["滚动","边界","逻辑属性","行内轴"],"aliases":["行内轴过度滚动","逻辑过度滚动","overscroll-behavior-inline"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overscroll-behavior-inline","order":478,"js":"overscrollBehaviorInline","specGroups":["CSS Overscroll Behavior"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"非替换的块级与行内块元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"144","firefox":"150","safari":"16","edge":"144"}},{"id":"css:overscroll-behavior-x","lang":"css","name":"overscroll-behavior-x","zh":"水平过度滚动","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制水平方向的连锁滚动行为","desc":"只作用于水平轴：contain 阻止横向滚动连锁到父级，none 同时禁用本地回弹，auto 为默认值。常用于横向滚动菜单、轮播，避免在容器边缘继续滑动时带动整个页面左右移动。它与 overscroll-behavior-y 互相独立。","syntax":"contain | none | auto","attrs":[],"values":[{"v":"auto","d":"默认行为（初始值）。"},{"v":"contain","d":"阻止横向连锁到父级滚动容器。"},{"v":"none","d":"阻止连锁并禁用本地回弹效果。"}],"example":".demo {\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n}","notes":["与 overscroll-behavior-y 独立，可以只禁用某一个方向。","Safari 16 起支持，更旧版本会忽略该声明。"],"keywords":["滚动","边界","水平","连锁"],"aliases":["水平过度滚动","横向连锁滚动","overscroll-behavior-x"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overscroll-behavior-x","order":479,"js":"overscrollBehaviorX","specGroups":["CSS Overscroll Behavior"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"非替换的块级与行内块元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"144","firefox":"150","safari":"16","edge":"18"}},{"id":"css:overscroll-behavior-y","lang":"css","name":"overscroll-behavior-y","zh":"垂直过度滚动","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"控制垂直方向的连锁滚动行为","desc":"只作用于垂直轴，最典型的用途是让弹窗、侧边抽屉或聊天列表滚到底后不再带动页面滚动（contain），或彻底关闭下拉刷新与回弹（none）。默认 auto 表示允许连锁滚动，它与 overscroll-behavior-x 独立，可分别设置两个方向。","syntax":"contain | none | auto","attrs":[],"values":[{"v":"auto","d":"默认行为（初始值）。"},{"v":"contain","d":"阻止纵向连锁到父级滚动容器。"},{"v":"none","d":"阻止连锁并禁用回弹，常用于关闭下拉刷新。"}],"example":".demo {\n  max-height: 320px;\n  overflow-y: auto;\n  overscroll-behavior-y: contain;\n}","notes":["Safari 16 起支持，旧版浏览器忽略该声明，必要时可用脚本兜底。","与 overscroll-behavior-x 独立设置，避免影响横向滚动。"],"keywords":["滚动","边界","垂直","连锁"],"aliases":["垂直过度滚动","纵向连锁滚动","overscroll-behavior-y"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overscroll-behavior-y","order":480,"js":"overscrollBehaviorY","specGroups":["CSS Overscroll Behavior"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"非替换的块级与行内块元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"144","firefox":"150","safari":"16","edge":"18"}},{"id":"css:scroll-axis-lock","lang":"css","name":"scroll-axis-lock","zh":"滚动轴锁定","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"锁定滚动容器当前滚动的方向轴","desc":"让滚动容器在识别出用户主要滚动方向后锁定到该轴，避免触摸板或触屏斜向滑动时在水平与垂直方向之间来回抖动。auto 为默认行为，none 关闭锁定。属于很新的特性，目前只有最新版 Chromium 内核实现，其他浏览器会直接忽略。","syntax":"auto | none","attrs":[],"values":[{"v":"auto","d":"默认行为，浏览器可自行锁定滚动轴（初始值）。"},{"v":"none","d":"关闭轴锁定，两个方向都可自由滚动。"}],"example":".demo {\n  overflow: auto;\n  scroll-axis-lock: auto;\n}","notes":["很新的属性，目前仅 Chrome 153 起支持，Firefox、Safari、Edge 尚未实现。","对可双向滚动的容器最有用，普通纵向滚动区域几乎看不出差异。"],"keywords":["滚动","方向","锁定","实验性"],"aliases":["滚动轴锁定","方向锁定","scroll-axis-lock"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-axis-lock","order":527,"js":"scrollAxisLock","specGroups":["CSS Overflow"],"meta":{"initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"滚动容器","computed":"按指定值","tier":"core"},"browser":{"chrome":"153","firefox":"✗","safari":"✗","edge":"✗"}},{"id":"css:scroll-behavior","lang":"css","name":"scroll-behavior","zh":"滚动行为","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置滚动是平滑还是瞬间跳转","desc":"auto（初始值）让锚点跳转、scrollIntoView 等滚动立即完成；smooth 用浏览器平滑动画滚动，适合目录跳转与返回顶部。该属性写在滚动容器上才生效，整页平滑滚动通常设在 html 上。它只影响由脚本或锚点触发的滚动，不改变用户拖拽滚动的行为。","syntax":"auto | smooth","attrs":[],"values":[{"v":"auto","d":"立即跳转（初始值）。"},{"v":"smooth","d":"平滑滚动到目标位置。"}],"example":".demo {\n  scroll-behavior: smooth;\n  overflow-y: auto;\n}","notes":["写在滚动容器上生效；整页平滑滚动一般设在 html 元素上。","可用 @media (prefers-reduced-motion: reduce) 改回 auto，照顾晕动症用户。"],"keywords":["滚动","平滑","锚点","跳转"],"aliases":["平滑滚动","滚动行为","scroll-behavior"],"status":"standard","statusLabel":"标准","hot":false,"tags":[],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-behavior","order":528,"js":"scrollBehavior","specGroups":["CSS Overflow"],"meta":{"initial":"auto","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"滚动盒","computed":"按指定值","tier":"core"},"browser":{"chrome":"61","firefox":"36","safari":"15.4","edge":"79"}},{"id":"css:scroll-margin","lang":"css","name":"scroll-margin","zh":"滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"简写设置滚动对齐时元素的外边距","desc":"定义元素在滚动吸附与 scrollIntoView 对齐时向外扩展的“外边距”，让停靠位置离容器边缘留出空间，常用于避开吸顶导航。取 1–4 个长度值，展开规则与 margin 简写相同，允许负值。它不影响布局，只参与滚动对齐计算。","syntax":"<length>{1,4}","attrs":[],"values":[{"v":"<length>","d":"四边相同，如 16px。"},{"v":"<length>{1,4}","d":"按上、右、下、左规则展开，如 8px 0 64px。"},{"v":"负值","d":"也合法，会让对齐位置越过元素边界。"}],"example":".demo {\n  scroll-margin: 72px 0 0;\n}","notes":["展开为 scroll-margin-top/right/bottom/left 四个长写属性。","只影响滚动吸附与对齐位置，不改变布局尺寸。","横排页面常用 scroll-margin-top 为吸顶导航留出高度。"],"keywords":["滚动","吸附","边距","锚点"],"aliases":["滚动外边距","吸附间距","scroll-margin"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin","order":530,"js":"scrollMargin","specGroups":["CSS Scroll Snap"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"69","firefox":"90","safari":"14.1","edge":"79"}},{"id":"css:scroll-margin-block","lang":"css","name":"scroll-margin-block","zh":"块轴滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置块轴方向的滚动外边距","desc":"逻辑属性，横排文字下映射到 scroll-margin-top 与 scroll-margin-bottom，竖排时映射到左右两侧。取 1–2 个长度值，分别对应块轴起点与终点。用于让滚动吸附或锚点定位在纵向留出固定偏移，且写法不依赖书写方向。","syntax":"<length>{1,2}","attrs":[],"values":[{"v":"<length>","d":"块轴两端相同，如 24px。"},{"v":"<length>{1,2}","d":"两个值分别为 block-start 与 block-end，如 64px 16px。"}],"example":".demo {\n  scroll-margin-block: 64px 16px;\n}","notes":["横排文字下等价于 scroll-margin-top 与 scroll-margin-bottom。","展开为 scroll-margin-block-start 与 scroll-margin-block-end。"],"keywords":["滚动","吸附","逻辑属性","块轴"],"aliases":["块轴滚动外边距","逻辑滚动边距","scroll-margin-block"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-block","order":531,"js":"scrollMarginBlock","specGroups":["CSS Scroll Snap"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-block-end","lang":"css","name":"scroll-margin-block-end","zh":"块轴末端滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置块轴末端的滚动外边距","desc":"单独控制块轴终点的滚动偏移：横排文字下即 scroll-margin-bottom，竖排时对应左侧或右侧。只影响滚动吸附与 scrollIntoView 的对齐位置，不占据布局空间。需要只调整一端（例如底部留白避开浮动按钮）时使用。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 24px，负值也合法。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-block-end: 24px;\n}","notes":["横排文字下等价于 scroll-margin-bottom。","与 scroll-margin-block-start 一起构成 scroll-margin-block 简写。"],"keywords":["滚动","吸附","逻辑属性","块轴"],"aliases":["块轴末端边距","逻辑滚动边距","scroll-margin-block-end"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-block-end","order":532,"js":"scrollMarginBlockEnd","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-block-start","lang":"css","name":"scroll-margin-block-start","zh":"块轴起始滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置块轴起点的滚动外边距","desc":"单独控制块轴起点的滚动偏移：横排文字下即 scroll-margin-top，竖排时对应右侧或左侧。最典型的用法是给锚点元素设置等于吸顶导航高度的值，让滚动定位后标题不被导航遮住。只影响滚动对齐，负值也合法。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 72px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-block-start: 72px;\n}","notes":["横排文字下等价于 scroll-margin-top，是避开吸顶导航最常用的写法。","属于逻辑属性，旧版浏览器需用 scroll-margin-top 兜底。"],"keywords":["滚动","吸附","逻辑属性","锚点"],"aliases":["块轴起始边距","逻辑滚动边距","scroll-margin-block-start"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-block-start","order":533,"js":"scrollMarginBlockStart","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-bottom","lang":"css","name":"scroll-margin-bottom","zh":"底部滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置底部的滚动对齐外边距","desc":"控制元素底部在滚动吸附与 scrollIntoView 对齐时额外留出的距离，影响停靠位置而非布局。取长度值，默认 0，负值合法。常用于页面底部有固定工具条或提示条时，让目标元素滚动后不被遮住。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 32px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-bottom: 32px;\n}","notes":["属于 scroll-margin 简写展开的长写属性。","只影响滚动停靠位置，视觉布局不会因此改变。"],"keywords":["滚动","吸附","边距","底部"],"aliases":["底部滚动边距","下滚动边距","scroll-margin-bottom"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-bottom","order":534,"js":"scrollMarginBottom","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"14.1","edge":"79"}},{"id":"css:scroll-margin-inline","lang":"css","name":"scroll-margin-inline","zh":"行内轴滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置行内轴方向的滚动外边距","desc":"逻辑属性，横排文字下映射到 scroll-margin-left 与 scroll-margin-right，竖排时映射到上下两侧。取 1–2 个长度值，分别对应行内轴起点与终点。用于横向滚动列表吸附、侧边定位等场景，使对齐位置不受书写方向影响。","syntax":"<length>{1,2}","attrs":[],"values":[{"v":"<length>","d":"行内轴两端相同，如 16px。"},{"v":"<length>{1,2}","d":"两个值分别为 inline-start 与 inline-end，如 24px 8px。"}],"example":".demo {\n  scroll-margin-inline: 24px 8px;\n}","notes":["横排文字下等价于 scroll-margin-left 与 scroll-margin-right。","展开为 scroll-margin-inline-start 与 scroll-margin-inline-end。"],"keywords":["滚动","吸附","逻辑属性","行内轴"],"aliases":["行内轴滚动外边距","逻辑滚动边距","scroll-margin-inline"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-inline","order":535,"js":"scrollMarginInline","specGroups":["CSS Scroll Snap"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-inline-end","lang":"css","name":"scroll-margin-inline-end","zh":"行内轴末端滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置行内轴末端的滚动外边距","desc":"单独控制行内轴终点的滚动偏移：横排 LTR 下即 scroll-margin-right（RTL 时为左侧），竖排时对应下侧。只影响滚动吸附与对齐停靠位置，不占据布局空间。适合横向轮播中只让右侧留出间距的场景。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 16px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-inline-end: 16px;\n}","notes":["横排 LTR 下等价于 scroll-margin-right，RTL 下对应左侧。","与 scroll-margin-inline-start 一起构成 scroll-margin-inline 简写。"],"keywords":["滚动","吸附","逻辑属性","行内轴"],"aliases":["行内轴末端边距","逻辑滚动边距","scroll-margin-inline-end"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-inline-end","order":536,"js":"scrollMarginInlineEnd","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-inline-start","lang":"css","name":"scroll-margin-inline-start","zh":"行内轴起始滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置行内轴起点的滚动外边距","desc":"单独控制行内轴起点的滚动偏移：横排 LTR 下即 scroll-margin-left，RTL 时对应右侧，竖排时对应上侧。常用于横向滚动列表，让第一项不被容器边缘或固定侧栏遮住。只影响滚动对齐位置，不改变布局尺寸。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 20px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-inline-start: 20px;\n}","notes":["横排 LTR 下等价于 scroll-margin-left。","属于逻辑属性，旧版浏览器需用 scroll-margin-left 兜底。"],"keywords":["滚动","吸附","逻辑属性","行内轴"],"aliases":["行内轴起始边距","逻辑滚动边距","scroll-margin-inline-start"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-inline-start","order":537,"js":"scrollMarginInlineStart","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-margin-left","lang":"css","name":"scroll-margin-left","zh":"左侧滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置左侧的滚动对齐外边距","desc":"控制元素左侧在滚动吸附与 scrollIntoView 对齐时额外留出的距离，默认 0，负值合法。横向轮播、时间轴等布局中，用它让停靠位置避开左侧固定栏或留出呼吸空间。只参与滚动停靠计算，不改变视觉布局。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 16px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-left: 16px;\n  overflow-x: auto;\n}","notes":["属于 scroll-margin 简写展开的长写属性。","RTL 布局中位置会反过来，写逻辑属性 scroll-margin-inline-start 更稳妥。"],"keywords":["滚动","吸附","边距","左侧"],"aliases":["左侧滚动边距","左滚动边距","scroll-margin-left"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-left","order":538,"js":"scrollMarginLeft","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"14.1","edge":"79"}},{"id":"css:scroll-margin-right","lang":"css","name":"scroll-margin-right","zh":"右侧滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置右侧的滚动对齐外边距","desc":"控制元素右侧在滚动吸附与 scrollIntoView 对齐时额外留出的距离，默认 0。横向布局中可让滚动停靠时右侧保留空隙，避免最后一项紧贴容器边缘或固定浮动按钮。只影响滚动对齐位置，不占据布局空间。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 16px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-right: 16px;\n}","notes":["属于 scroll-margin 简写展开的长写属性。","RTL 布局中可用 scroll-margin-inline-end 代替，语义更清晰。"],"keywords":["滚动","吸附","边距","右侧"],"aliases":["右侧滚动边距","右滚动边距","scroll-margin-right"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-right","order":539,"js":"scrollMarginRight","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"14.1","edge":"79"}},{"id":"css:scroll-margin-top","lang":"css","name":"scroll-margin-top","zh":"顶部滚动外边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置顶部的滚动对齐外边距","desc":"控制元素顶部在滚动吸附与 scrollIntoView 对齐时额外留出的距离，默认 0。最常用于避让吸顶导航：给标题或锚点设置等于导航高度的 scroll-margin-top，跳转后标题就不会被遮挡。只影响滚动停靠计算，不改变布局尺寸。","syntax":"<length>","attrs":[],"values":[{"v":"<length>","d":"长度值，如 72px。"},{"v":"0","d":"无额外偏移（初始值）。"}],"example":".demo {\n  scroll-margin-top: 72px;\n}","notes":["属于 scroll-margin 简写展开的长写属性，与 margin 无关。","吸顶导航高度变化时需同步调整该值，可用 CSS 变量统一维护。"],"keywords":["滚动","吸附","锚点","吸顶"],"aliases":["顶部滚动边距","上滚动边距","scroll-margin-top"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-margin-top","order":540,"js":"scrollMarginTop","specGroups":["CSS Scroll Snap"],"meta":{"initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"14.1","edge":"79"}},{"id":"css:scroll-marker-group","lang":"css","name":"scroll-marker-group","zh":"滚动标记组","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"为滚动容器创建滚动标记组","desc":"让滚动容器生成一个 ::scroll-marker-group 伪元素，用来集中容纳由 ::scroll-marker 生成的导航标记，类似轮播指示点。none 不生成，before 或 after 决定标记组出现在容器内容之前还是之后。属于 CSS Overflow 较新的滚动标记特性，目前仅 Chromium 实现。","syntax":"none | before | after","attrs":[],"values":[{"v":"none","d":"不生成滚动标记组（初始值）。"},{"v":"before","d":"标记组作为容器的第一个子元素。"},{"v":"after","d":"标记组作为容器的最后一个子元素。"}],"example":".demo {\n  overflow-x: auto;\n  scroll-marker-group: after;\n}","notes":["较新特性，Chrome/Edge 135 起支持，Firefox 与 Safari 尚未实现。","需配合 ::scroll-marker 伪元素使用，标记由子元素生成。"],"keywords":["滚动","标记","轮播","实验性"],"aliases":["滚动标记组","轮播指示点","scroll-marker-group"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-marker-group","order":541,"js":"scrollMarkerGroup","specGroups":["CSS Overflow"],"meta":{"initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"滚动容器","computed":"按指定值","tier":"core"},"browser":{"chrome":"135","firefox":"✗","safari":"✗","edge":"135"}},{"id":"css:scroll-padding","lang":"css","name":"scroll-padding","zh":"滚动内边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"简写设置滚动容器的吸附内边距","desc":"定义滚动容器可视区域内缩的“内边距”，吸附与滚动对齐时元素会停靠在这个内缩区域内，相当于给容器留出安全区。取 1–4 个 auto 或长度百分比值，展开规则与 padding 简写相同。它与 scroll-margin 一个作用于容器、一个作用于目标元素，常配合使用。","syntax":"[ auto | <length-percentage> ]{1,4}","attrs":[],"values":[{"v":"auto","d":"由浏览器决定，通常视为 0（初始值）。"},{"v":"<length-percentage>","d":"四个方向相同，如 72px。"},{"v":"<length-percentage>{1,4}","d":"按上、右、下、左展开，如 72px 0 0。"}],"example":".demo {\n  overflow-y: auto;\n  scroll-padding: 72px 0 0;\n}","notes":["展开为 scroll-padding-top/right/bottom/left 四个长写属性。","作用在滚动容器上，目标元素上的 scroll-margin 可以叠加生效。","百分比相对滚动容器的滚动视口尺寸计算。"],"keywords":["滚动","吸附","内边距","滚动容器"],"aliases":["滚动内边距","吸附内边距","scroll-padding"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-padding","order":542,"js":"scrollPadding","specGroups":["CSS Scroll Snap"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"按计算值插值","percentages":"相对滚动容器滚动端口","appliesTo":"滚动容器","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"14.1","edge":"79"}},{"id":"css:scroll-padding-block","lang":"css","name":"scroll-padding-block","zh":"块轴滚动内边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置滚动容器块轴方向的吸附内边距","desc":"逻辑属性，横排文字下等价于 scroll-padding-top 与 scroll-padding-bottom，竖排时映射到左右两侧。取 1–2 个 auto 或长度百分比值，分别对应块轴起点与终点，百分比相对滚动视口尺寸。它让吸附与 scrollIntoView 停靠时在纵向留出安全距离，相当于给容器划出内缩区域。","syntax":"[ auto | <length-percentage> ]{1,2}","attrs":[],"values":[{"v":"auto","d":"由浏览器决定，通常视为 0（初始值）。"},{"v":"<length-percentage>","d":"块轴两端相同，如 72px。"},{"v":"<length-percentage>{1,2}","d":"分别为 block-start 与 block-end，如 72px 0。"}],"example":".demo {\n  overflow-y: auto;\n  scroll-padding-block: 72px 0;\n}","notes":["展开为 scroll-padding-block-start 与 scroll-padding-block-end。","横排文字下等价于 scroll-padding-top 与 scroll-padding-bottom。"],"keywords":["滚动","吸附","逻辑属性","内边距"],"aliases":["块轴滚动内边距","逻辑滚动内边距","scroll-padding-block"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画","简写"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-padding-block","order":543,"js":"scrollPaddingBlock","specGroups":["CSS Scroll Snap"],"meta":{"initial":"由各长写属性决定","inherited":"否","animation":"按计算值插值","percentages":"相对滚动容器滚动端口","appliesTo":"滚动容器","computed":"由各长写属性决定","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}},{"id":"css:scroll-padding-block-end","lang":"css","name":"scroll-padding-block-end","zh":"块轴末端滚动内边距","cat":"scroll","catName":"滚动与溢出","catEn":"","catOrder":10,"summary":"设置滚动容器块轴末端的内边距","desc":"单独控制块轴终点的吸附内缩：横排文字下即 scroll-padding-bottom，竖排时对应左侧或右侧。取 auto 或长度百分比，默认 auto（通常视为 0）。它只影响吸附对齐与 scrollIntoView 的停靠位置，不改变内容布局，适合底部有固定元素时留出空间。","syntax":"auto | <length-percentage>","attrs":[],"values":[{"v":"auto","d":"由浏览器决定（初始值）。"},{"v":"<length-percentage>","d":"长度或百分比，如 24px、5%。"}],"example":".demo {\n  overflow-y: auto;\n  scroll-padding-block-end: 24px;\n}","notes":["横排文字下等价于 scroll-padding-bottom。","与 scroll-padding-block-start 一起构成 scroll-padding-block 简写。"],"keywords":["滚动","吸附","逻辑属性","内边距"],"aliases":["块轴末端内边距","逻辑滚动内边距","scroll-padding-block-end"],"status":"standard","statusLabel":"标准","hot":false,"tags":["可动画"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scroll-padding-block-end","order":544,"js":"scrollPaddingBlockEnd","specGroups":["CSS Scroll Snap"],"meta":{"initial":"auto","inherited":"否","animation":"按计算值插值","percentages":"相对滚动容器滚动端口","appliesTo":"滚动容器","computed":"按指定值","tier":"core"},"browser":{"chrome":"69","firefox":"68","safari":"15","edge":"79"}}]);
